'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['applyLedgerCredit']);
const { applyLedgerCredit } = api;

const original = [
  { key: 'a', reserve: 10, bonus: 20, tokens: 30 },
  { key: 'b', reserve: 0, bonus: 1, tokens: 2 }
];
const credited = applyLedgerCredit('credit:bonus', 'a', 5, original);
assert.deepStrictEqual(credited, {
  ok: true,
  accounts: [
    { key: 'a', reserve: 10, bonus: 25, tokens: 30 },
    { key: 'b', reserve: 0, bonus: 1, tokens: 2 }
  ],
  message: 'bonus credited by 5; new balance: 25.'
});
assert.deepStrictEqual(original, [
  { key: 'a', reserve: 10, bonus: 20, tokens: 30 },
  { key: 'b', reserve: 0, bonus: 1, tokens: 2 }
]);
assert.notStrictEqual(credited.accounts[0], original[0]);
assert.notStrictEqual(credited.accounts[1], original[1]);

const missing = applyLedgerCredit('credit:tokens', 'missing', 3, original);
assert.deepStrictEqual(missing, {
  ok: false,
  accounts: original,
  message: 'Account missing was not found.'
});
assert.notStrictEqual(missing.accounts, original);
assert.notStrictEqual(missing.accounts[0], original[0]);
missing.accounts[0].reserve = 999;
assert.strictEqual(original[0].reserve, 10);

assert.deepStrictEqual(applyLedgerCredit('credit:reserve', 'x', 1, []), {
  ok: false,
  accounts: [],
  message: 'Account x was not found.'
});
assert.strictEqual(applyLedgerCredit('credit:tokens', 'b', 4, original).accounts[1].tokens, 6);

for (const args of [
  ['bad', 'a', 1, original],
  ['credit:reserve', '', 1, original],
  ['credit:reserve', 2, 1, original],
  ['credit:reserve', 'a', '1', original],
  ['credit:reserve', 'a', 1, null],
  ['credit:reserve', 'a', 1, [{ key: 'a', reserve: 0, bonus: 0 }]],
  ['credit:reserve', 'a', 1, [{ key: '', reserve: 0, bonus: 0, tokens: 0 }]],
  ['credit:reserve', 'a', 1, [{ key: 'a', reserve: '0', bonus: 0, tokens: 0 }]]
]) assert.throws(() => applyLedgerCredit(...args), TypeError);

for (const amount of [0, -1, 1.5, Number.MAX_SAFE_INTEGER + 1]) {
  assert.throws(() => applyLedgerCredit('credit:reserve', 'a', amount, original), RangeError);
}
assert.throws(() => applyLedgerCredit('credit:reserve', 'a', 1, [
  { key: 'a', reserve: 0, bonus: 0, tokens: 0 },
  { key: 'a', reserve: 1, bonus: 1, tokens: 1 }
]), RangeError);
assert.throws(() => applyLedgerCredit('credit:reserve', 'a', 1, [
  { key: 'a', reserve: -1, bonus: 0, tokens: 0 }
]), RangeError);
assert.throws(() => applyLedgerCredit('credit:reserve', 'a', 1, [
  { key: 'a', reserve: Number.MAX_SAFE_INTEGER, bonus: 0, tokens: 0 }
]), RangeError);

